/**
 * Diagram typefaces and deterministic text measurement.
 *
 * Diagram text uses four bundled faces (SIL Open Font License, see `src/assets/fonts`). Their
 * advance widths are stored in `font-metrics.json`, generated by `scripts/font-metrics.mjs` from
 * the same files. Wrapping and sizing read that table, never the DOM, so the compiler, the browser
 * and the CLI break every label at the same place.
 */
import metrics from './font-metrics.json';

export type FontRole = 'sans' | 'serif' | 'mono';
export const FONT_ROLES: FontRole[] = ['sans', 'serif', 'mono'];

export interface FontFace {
  /** Registered family name; unique so an installed copy of the font is never used instead. */
  family: string;
  weight: number;
  file: string;
}

export const FACES = {
  'sans-500': { family: 'Draft Inter', weight: 500, file: 'inter-latin-500-normal.woff2' },
  'sans-600': { family: 'Draft Inter', weight: 600, file: 'inter-latin-600-normal.woff2' },
  'serif-600': {
    family: 'Draft Source Serif',
    weight: 600,
    file: 'source-serif-4-latin-600-normal.woff2',
  },
  'mono-500': {
    family: 'Draft JetBrains Mono',
    weight: 500,
    file: 'jetbrains-mono-latin-500-normal.woff2',
  },
} satisfies Record<string, FontFace>;

export type FaceId = keyof typeof FACES;

const FALLBACK: Record<FontRole, string> = {
  sans: 'Inter, Arial, sans-serif',
  serif: "'Source Serif 4', Georgia, serif",
  mono: "'JetBrains Mono', Menlo, Consolas, monospace",
};

/** Face used for each role: titles are a little heavier than annotations in sans-serif. */
export const faceFor = (role: FontRole, title: boolean): FaceId =>
  role === 'serif' ? 'serif-600' : role === 'mono' ? 'mono-500' : title ? 'sans-600' : 'sans-500';

export const fontStack = (role: FontRole) => {
  const face = FACES[faceFor(role, true)];
  return `'${face.family}', ${FALLBACK[role]}`;
};

/** A text style: which face, at what size and line height. */
export interface TypeProfile {
  role: FontRole;
  face: FaceId;
  family: string;
  weight: number;
  size: number;
  lineHeight: number;
}

export function typeProfile(
  role: FontRole,
  title: boolean,
  size: number,
  lineHeight: number,
): TypeProfile {
  const face = faceFor(role, title);
  return { role, face, family: fontStack(role), weight: FACES[face].weight, size, lineHeight };
}

type Table = { unitsPerEm: number; fallback: number; advances: Record<string, number> };
const TABLES = metrics as unknown as Record<FaceId, Table>;

/**
 * Width of `text` in `profile`, from the stored advance widths. Kerning is ignored, which only
 * ever overstates a width slightly, so measured text fits where this says it fits.
 */
export function measureText(text: string, profile: Pick<TypeProfile, 'face' | 'size'>) {
  const table = TABLES[profile.face];
  let units = 0;
  for (const char of text) units += table.advances[char] ?? table.fallback;
  return (units * profile.size) / table.unitsPerEm;
}

/** Break text into lines no wider than `width`, splitting over-long words by character. */
export function wrapLines(text: string, width: number, profile: TypeProfile): string[] {
  const fits = (s: string) => measureText(s, profile) <= width;
  const lines: string[] = [];
  for (const paragraph of String(text).split('\n')) {
    let line = '';
    for (const word of paragraph.split(/\s+/)) {
      if (!word) continue;
      if (!fits(word)) {
        if (line) lines.push(line);
        let part = '';
        for (const char of word) {
          if (part && !fits(part + char)) {
            lines.push(part);
            part = '';
          }
          part += char;
        }
        line = part;
        continue;
      }
      if (line && !fits(line + ' ' + word)) {
        lines.push(line);
        line = word;
      } else line += (line ? ' ' : '') + word;
    }
    lines.push(line);
  }
  return lines.length ? lines : [''];
}

/** Shorten text with an ellipsis so it fits in `width`. */
export function truncateText(text: string, width: number, profile: TypeProfile) {
  if (measureText(text, profile) <= width) return text;
  let out = text;
  while (out && measureText(out + '…', profile) > width) out = out.slice(0, -1);
  return out.trimEnd() + '…';
}
